#!/usr/bin/env python3
"""Publish ONLY independently source-verified ORIGINAL motion video counts.

Original public author-injected Godot Platformer character pose freeze versus
same-scene source normal controls, 12 paired scenes 24 original MP4 from
TempGlitch 2026 (copyright/license under isolated /data/var). Truly moving
rendered source videos, no synthetic local frame drop or user owner media.

All 24 original MP4 exact LFS SHA256+size receipts checked, image-only native
FFmpeg freeze / 5fps pixel+local/phase optical flow features frozen BEFORE
joining original author buggy/normal labels. Source says creator injected
character animation freeze; exact independent human-approved bad timing and
subjective rating unavailable. Report this explicitly and never overclaim.

Compact method TP/FP/FN/TN+abstentions, source-scene bootstrap and actual CPU
resource; original video paths, frames, source identifiers and per-case raw
scores remain outside Git, no model files or original licensed media copied.
"""
from pathlib import Path
import json,hashlib
ROOT=Path('/data/var/perceptual-independent-20261024/tempglitch-pose-frozen-external-20261025')
DOC=Path(__file__).resolve().parents[2]/'docs/research'
PUB=DOC/'perceptual-tempglitch-real-character-pose-video-control-2026-10-25.json'
REPORT=DOC/'perceptual-tempglitch-frozen-pose-source-video-2026-10-25.md'


def read(name):
 b=(ROOT/name).read_bytes();return json.loads(b),hashlib.sha256(b).hexdigest()

def pct(x):return 'n/a' if x is None else f'{x*100:.1f}%'

def main():
 if PUB.exists() or REPORT.exists():print('PRIOR_ORIGINAL_TEMPORAL_VIDEO_REPORT_PRESERVED');return
 plan,hplan=read('source_original_12_platformer_pairs_fixed_selection_20261025.json')
 receipts,hrec=read('source_24_original_MP4_verified_SHA256_receipts_20261025.json')
 pixels,hpix=read('24_actual_original_video_fullframe_vs_character_appearance_features_FILTER_FIXED_20261025.json')
 score,hscore=read('24_original_external_frozen_animation_vs_normal_method_comparisons_20261025.json')
 assert plan['selected_independent_source_scene_pairs']==12
 assert len(receipts['completed'])==24 and len(pixels['source_label_blind_results'])==24
 assert pixels['status']=='complete'
 assert score['source_hashes']['frozen_original_12_pair_selection']==hplan
 assert score['source_hashes']['all24_original_video_pixel_predictions_before_author_gold']==hpix
 assert len(score['actual_original_source_method_metrics'])==5
 methods={}
 for name,v in score['actual_original_source_method_metrics'].items():
  assert v['TP']+v['FN']+v['abstained_original_positive_n']==12
  assert v['FP']+v['TN']+v['abstained_original_normal_control_n']==12
  methods[name]=v
  print('ORIGINAL_ENGINE_SOURCE_24_CLIPS',name,'TP',v['TP'],'FP',v['FP'],'FN',v['FN'],'TN',v['TN'],'ABSTAIN_POS',v['abstained_original_positive_n'],'ABSTAIN_NORMAL',v['abstained_original_normal_control_n'],'AUC',v['continuous_run_score_AUROC'])
 out={'date':'2026-10-25','status':'PARTIAL — source original moving gameplay frozen-character bug visual detector experiment measured, no independently human-blind objectionability or temporal event intervals, no general automatic QA model qualified','source':'TempGlitch original 2026 in-engine authored frozen character pose vs original normal Godot Platformer footage, asgaardlab/TempGlitch MIT dataset source; original scene ID matched by full filename family, not merely suffix','source_provenance_sha256':{'source_frozen_12_original_scenes_before_pixels':hplan,'exact_original_24_MP4_LFS_SHA_verified_file_receipts':hrec,'source_blind_native_FFmpeg+5fps_region_Farneback_metrics':hpix,'external_authored_glitch_vs_normal_error_counts':hscore},'original_independent_scene_pairs':12,'original_video_files_CPU_decoded':24,'source_media_megabytes':plan['total_download_MB'],'independent_source_truth_scope':'Author intentionally injected character animation pose remains stationary while rest game may animate. Source original normal same numeric game scene family; labels engineered by authors, no human blind subjectively objectionable ratings, no source frame-accurate onset/end labels.','method_frozen_conditions':pixels['config'],'observed_original_source_binary_and_rank_performance':methods,'run_resource':{'GPU_used':False,'FFmpeg_native_source_and_5fps_image_CPU_seconds':pixels.get('run_wall_seconds'),'peak_video_pixel_CPU_RSS_KB':pixels.get('run_peak_RSS_KB'),'original_source_files_in_project_git':False,'original_video_model_inference_queried':False},'scientific_limits':['Source video-size capped 70MB per original matched pair and 12 selected via fixed SHA sort from 27 eligible original Platformer scenes; no whole 1500 set or independent engine domain.','Godot author injected character pose bugs are not genuine unplanned camera video playback frozen frames. No ground truth human time-coded fault masks means only video-level bug class detection.','No player/rig bounding boxes or latent engine pose logs available to video pixel detector; center ROI is a guess, not a certified character area.','Normal source clips may show pauses, stationary characters, camera cuts and intentional non-motion; no independent new human rating of false positive phenomena.','Frame-only low-level CV detects image stasis or relative motion, not whether an action, mechanical assembly, joint or player intent is correct.','Any method appearing strong on 12 source scene pairs has wide exact confidence and must be externally verified on previously unexamined engine, user production source and human clear event labels before approval.','Results are not direct model-inference on Thor, and none qualifies complete multimodal video/audible synchronization.','Original third-party game media and per-case source identifiers retained in /data/var, not distributed in Git.','Previously denied high-resolution owner video tail-frame retrieval and other Spotlight video analysis were not reattempted, and no uncertain Calendar send was repeated.']}
 PUB.write_text(json.dumps(out,indent=2)+'\n')
 rows=[]
 for name,v in methods.items():
  rows.append(f"| {name.replace('_',' ')} | {v['TP']}/{v['TP']+v['FN']} | {v['FP']}/{v['FP']+v['TN']} | {v['FN']} | +{v['abstained_original_positive_n']} / +{v['abstained_original_normal_control_n']} | {pct(v['continuous_run_score_AUROC'])} | {v['source_scene_matched_bootstrap_95pct_CI']['AUROC']} |")
 text='''# Real source gameplay animation freeze: is whole-frame or region-aware video analysis enough?\n\n**25 October 2026. Research verdict PARTIAL.** The owner asked for actual judgement of dynamic visuals and video motion, not a fake frame-difference pass. The preceding original VideoSham benchmark evaluated deliberate video-editor frame changes, whereas the published TempGlitch VLM source tables measured in-game engine animation anomalies but no local image pixel algorithm was actually run. This independent new video-source test uses **24 original videos (twelve creator-injected frozen CHARACTER ANIMATION, twelve scene-ID/family-matched normal gameplay clips)** in the original [TempGlitch dataset](https://huggingface.co/datasets/asgaardlab/TempGlitch) (2026, Godot Platformer game, source author engine-injected labels, MIT dataset release). All original source MP4s were fetched from the pinned public release and verified by exact official original content SHA256 and bytes. **No source output or defect footage was synthetically generated by our scripts.** Original 716.73MB videos and per-scene output remain outside project Git. This study is one image-pixel focused continuation that does not repeat original previous VideoSham/MVTec/SADU experiments.\n\nSelection, source provenance and controls: from the complete independently inventoried TempGlitch release, we selected **all potential original source pairs with both Platformer Buggy and Normal files sharing full scene family/index identity and combined file size <=70MB**, then used a fixed SHA256 ordering to select twelve of twenty-seven eligible source-scene pairs. This was frozen before downloading or decoding any video content. The size cap introduces a strong potential bias toward shorter/lower bitrate/compressible clips. Other author glitch filenames in the first twenty-one cases did not establish unambiguous same-environment pairing and were deliberately excluded rather than cross-matched by numeric suffix. These are genuine source author labels, **not new independent human adjudication** or natural playback stalls.\n\nAll five methods were fixed before examining video pixels: native-frame official FFmpeg `freezedetect=n=-50dB:d=0.6`, full-frame 5FPS grayscale low-change runs, center ROI low-change while outside moves, translationally registered center ROI low-change while outside moves, and local-versus-outer Farneback optical-flow mismatch. The center ROI was a generic central-person assumption, not an object detector; no annotated person location or engine pose target was given. Decoded each actual source video at native FPS for official FFmpeg; sampled five frames per second at 192 by 108 pixel grayscale for all other methods, CPU only, one thread, no Nitro RTX or Thor resources. The image-only outputs were frozen before the original author bug/normal labels were joined for scoring. Five binary detectors share the same twelve author-glitch/normal source pairs; missing decoding counts as **abstain**, not success.\n\n## Original author fault labels: measured positives, misses and false good-video flags\n\n| Frozen-source rule | Original frozen-animation clips found | False alerts on original normal gameplay controls | Misses | Abstained (bug / normal) | ROC AUC for original author bug type | Matched source-scene bootstrap 95% AUC |\n|---|---:|---:|---:|---:|---:|---|\n'''+"\n".join(rows)+"\n\n"
 text+='''The compact report [`perceptual-tempglitch-real-character-pose-video-control-2026-10-25.json`](perceptual-tempglitch-real-character-pose-video-control-2026-10-25.json) retains exact source-positive/negative counts, source-authored classification recall, false alarms, original-scene paired uncertainty, model-free thresholds, source SHA receipts, decoded sample counts, frame-rate/duration metadata and CPU runtime. The source scene is **a character's animation pose becoming frozen**, while camera, objects and background may continue moving and video frames are valid. Therefore detecting frozen **whole** image frames is the wrong observable: a no-freeze result from FFmpeg does not establish absence of original frozen-body animation. Center-crop image differencing and optical flow may also fail because pose can be stationary while the character translates and the camera moves; without actual person/rig tracking, a moving torso region does not prove animation quality. Similarly a true source normal video can intentionally display little motion. The source externally annotated which game code was intentionally changed, but no exact frame intervals or independent audience ratings are available. Consequently ROC AUC and author-label classification are distinct from human-objectionable temporal video quality, timing F1 and production render acceptance.\n\nThe appropriate immediately usable tier remains *authoritative source animation state and physical kinematic constraints where available*, plus original expected event timing, valid captured frame/audio stream alignment, object/pose tracking and independently rated playback inspection. FFmpeg only checks full-frame freezing; optical flow estimates changes in pixel movement, not action correctness or aesthetic continuity. A specialized video transformer/pose model could be researched next, but must be independently validated on original source-labelled physically consistent vs inconsistent movement and truly human-reviewed clean/defective production streams before automatic approval. Neither this limited source test nor prior VLM author tables qualifies a universal perceptual motion judge. Existing owner warehouse render/GPU remains unaffected.\n\n**Unresolved:** independently verified natural discontinuities and audio-video synchronization with correct onset/offset and real clean, same FPS/codec controls, plus actor segmentation/pose or authoritative 3D animation ground truth. No previously denied operations or uncertain Calendar events were repeated; no new automation was made. Research status PARTIAL.\n'''
 REPORT.write_text(text)
 print('NEW_REAL_SOURCE_VIDEO_REPORT_READY',PUB.stat().st_size,'JSON_BYTES',REPORT.stat().st_size,'MD_BYTES','SCENE_N',len(rows))
if __name__=='__main__':main()
